    wbs_data."id",
    project."id",
    wbs_data."code",
    wbs_data."title",
    wbs_data."type"::"WbsItemType",
    wbs_data."status"::"WbsItemStatus",
    wbs_data."owner",
    wbs_data."startDate",
    wbs_data."dueDate",
    0.00,
    0.00,
    wbs_data."progress",
    wbs_data."description",
    wbs_data."sortOrder",
    CURRENT_TIMESTAMP,
    CURRENT_TIMESTAMP
FROM project
CROSS JOIN wbs_data;

UPDATE "WbsItem" child
SET "parentId" = parent."id"
FROM "WbsItem" parent
WHERE child."projectId" = (SELECT "id" FROM "Project" WHERE "code" = 'TEST-001' LIMIT 1)
  AND parent."projectId" = child."projectId"
  AND child."code" LIKE '%.%'
  AND parent."code" = regexp_replace(child."code", '\.[^.]+$', '');

